static void spiceCheck(){if(failed_c()){char error[1841];getmsg_c("LONG",sizeof(error),error);reset_c();throw std::runtime_error(error);}}
static State trajectory(double t,bool second){
 const double b=second ? 1 : 0;
 return {20000+.5*t+.001*t*t+1e-7*t*t*t+b*(1000+.1*t),-15000+1.5*t-.0005*t*t+2e-7*t*t*t+b*(-2000-.2*t),3000-.2*t+.0001*t*t-1e-8*t*t*t+b*(500+.05*t),
 .5+.002*t+3e-7*t*t+b*.1,1.5-.001*t+6e-7*t*t-b*.2,-.2+.0002*t-3e-8*t*t+b*.05};
}
