static CelestialBody *body(){auto *b=dynamic_cast<CelestialBody *>(Moderator::Instance()->GetConfiguredObject("Probe"));require(b,"User-body configured object missing");return b;}
static QStringList kernels(){QStringList result;for(const auto &p:body()->GetStringArrayParameter(body()->GetParameterID("OrbitSpiceKernelName")))result.append(QString::fromStdString(p));return result;}
static QJsonArray json(const State &value){QJsonArray result;for(double x:value)result.append(x);return result;}
